//! 🗃️ Journaled physical entry commands with exclusive destination publication.

use super::*;
use semio_framework_hash::Sha256;

#[path="🕰️history/🦀️.rs"]
pub(crate) mod history;

fn command_id()->String{format!("{:x}-{:x}-{:x}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_nanos(),SERIAL.fetch_add(1,Ordering::Relaxed))}
fn movement_error(path:&str,failure:std::io::Error)->Error{if failure.kind()==std::io::ErrorKind::AlreadyExists{error(ErrorKind::Conflict,path,"Destination already exists")}else{io(path,failure)}}
fn entry(path:&str,directory:bool)->Entry{Entry{path:path.into(),name:path.rsplit('/').next().unwrap_or(path).into(),directory}}
fn matching(before:&Stamp,after:&Stamp)->bool{before.identity==after.identity&&before.length==after.length&&before.modified==after.modified}
pub(super) fn namespace_continuity(published:[(u64,u64);3],current:[(u64,u64);3])->bool{published.iter().all(|v|v.0==published[0].0)&&current.iter().all(|v|v.0==current[0].0)&&published.iter().zip(current).all(|(before,after)|before.1==after.1)}

fn hex_digest(bytes:[u8;32])->String{let digits=b"0123456789abcdef";let mut result=String::with_capacity(64);for byte in bytes{result.push(digits[(byte>>4)as usize]as char);result.push(digits[(byte&15)as usize]as char);}result}
pub(super) fn bytes_fingerprint(bytes:&[u8])->String{hex_digest(Sha256::digest(bytes))}
fn tree_fingerprint(nodes:&[TreeNode])->String{let mut hash=Sha256::new();for(index,node)in nodes.iter().enumerate(){hash.update(&(node.suffix.len()as u64).to_le_bytes());hash.update(node.suffix.as_bytes());hash.update(&[u8::from(node.directory)]);hash.update(&node.stamp.identity.1.to_le_bytes());hash.update(&node.stamp.length.to_le_bytes());if index>0{hash.update(&node.stamp.change.0.to_le_bytes());hash.update(&node.stamp.change.1.to_le_bytes());}if let Some(time)=node.stamp.modified{hash.update(&[1]);let nanos=match time.duration_since(UNIX_EPOCH){Ok(value)=>value.as_nanos()as i128,Err(value)=>-(value.duration().as_nanos()as i128)};hash.update(&nanos.to_le_bytes());}else{hash.update(&[0]);}}hex_digest(hash.finalize())}
fn tree_matches(expected:&[TreeNode],current:&[TreeNode])->bool{expected.len()==current.len()&&expected.iter().zip(current).enumerate().all(|(index,(before,after))|before.suffix==after.suffix&&before.directory==after.directory&&if index==0{matching(&before.stamp,&after.stamp)}else{before.stamp==after.stamp})}

pub(super) fn validate_tree_projection(root_units:usize,destination:&str,nodes:&[TreeNode])->Result<(),Error>{
    if nodes.len()>MAXIMUM_DIRECTORY_ENTRIES{return Err(error(ErrorKind::TooManyEntries,destination,"Tree exceeds 4096 total entries"));}if let Some(name)=destination.strip_prefix(&format!("{STATE}/segments/")){let pieces=name.split('/').collect::<Vec<_>>();if pieces.len()!=2||pieces[0].len()!=8||!pieces[0].bytes().all(|b|b.is_ascii_digit()||matches!(b,b'a'..=b'f'))||!pieces[1].strip_suffix(".retained").is_some_and(|id|!id.is_empty()&&id.len()<=64&&id.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||b==b'-')){return Err(error(ErrorKind::InvalidPath,destination,"Selected retained destination required"));}}else{validate_relative(destination)?;}
    let mut seen=std::collections::BTreeMap::new();let mut previous="";for(index,node)in nodes.iter().enumerate(){if(index==0&&!node.suffix.is_empty())||(index>0&&(node.suffix.is_empty()||node.suffix.as_str()<=previous))||seen.contains_key(node.suffix.as_str()){return Err(error(ErrorKind::Conflict,destination,"Complete sorted tree roster required"));}if !node.suffix.is_empty(){validate_relative(&node.suffix)?;let parent=node.suffix.rsplit_once('/').map_or("",|value|value.0);if seen.get(parent)!=Some(&true){return Err(error(ErrorKind::Conflict,destination,"Observed parent directory required"));}}let units=root_units+1+destination.encode_utf16().count()+if node.suffix.is_empty(){0}else{1+node.suffix.encode_utf16().count()};if units>MAXIMUM_PATH_UNITS{return Err(error(ErrorKind::InvalidPath,destination,"Projected physical path exceeds 256 UTF-16 units"));}seen.insert(node.suffix.as_str(),node.directory);previous=&node.suffix;}if nodes.is_empty()&&root_units+1+destination.encode_utf16().count()>MAXIMUM_PATH_UNITS{return Err(error(ErrorKind::InvalidPath,destination,"Projected physical path exceeds 256 UTF-16 units"));}Ok(())
}

impl Workspace{
    fn content_fingerprint(&self,path:&str,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<(String,Stamp),Error>{
        checkpoint(cancel,path)?;let mut file=native::open_in(&self.root,&self.anchor,path).map_err(|e|io(path,e))?;let facts=file.metadata().map_err(|e|io(path,e))?;if !facts.is_file(){return Err(error(ErrorKind::NotFile,path,"Regular managed file required"));}let before=native::stamp(&file).map_err(|e|io(path,e))?;if before.length>MAXIMUM_MANAGED_FILE_BYTES{return Err(error(ErrorKind::TooLarge,path,"Managed file verification exceeds 64 MiB"));}
        let mut hash=Sha256::new();let mut chunk=[0u8;16384];let mut completed=0u64;while completed<before.length{checkpoint(cancel,path)?;let extent=(before.length-completed).min(chunk.len()as u64)as usize;let count=file.read(&mut chunk[..extent]).map_err(|e|io(path,e))?;if count==0{return Err(error(ErrorKind::Conflict,path,"Managed file shrank during verification"));}hash.update(&chunk[..count]);completed+=count as u64;tick(progress,Stage::Reading,completed,Some(before.length));}
        checkpoint(cancel,path)?;let after=native::stamp(&file).map_err(|e|io(path,e))?;let current=native::stamp(&native::open_in(&self.root,&self.anchor,path).map_err(|e|io(path,e))?).map_err(|e|io(path,e))?;if before!=after||before!=current{return Err(error(ErrorKind::Conflict,path,"Managed file changed during verification"));}Ok((hex_digest(hash.finalize()),before))
    }

    fn tree_census(&self,path:&str,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<Arc<[TreeNode]>,Error>{
        let device=native::stamp(&self.anchor).map_err(|e|io(path,e))?.identity.0;let mut pending=vec![String::new()];let mut nodes=Vec::new();while let Some(suffix)=pending.pop(){checkpoint(cancel,path)?;let relative=if suffix.is_empty(){path.to_owned()}else{format!("{path}/{suffix}")};bounded(&self.root.join(&relative))?;if !suffix.is_empty(){validate_relative(&suffix)?;}let file=native::open_in(&self.root,&self.anchor,&relative).map_err(|e|error(ErrorKind::Boundary,&relative,e))?;let facts=file.metadata().map_err(|e|io(&relative,e))?;let before=native::stamp(&file).map_err(|e|io(&relative,e))?;
            if native::reparse(&facts)||facts.file_type().is_symlink()||(!facts.is_dir()&&!facts.is_file())||before.identity.0!=device{return Err(error(ErrorKind::Boundary,&relative,"One nofollow physical tree namespace required"));}if nodes.len()==MAXIMUM_DIRECTORY_ENTRIES{return Err(error(ErrorKind::TooManyEntries,path,"Tree exceeds 4096 total entries"));}
            if facts.is_dir(){let names=native::names(&self.root,&self.anchor,&relative,cancel).map_err(|e|io(&relative,e))?;if names.len()+nodes.len()+pending.len()+1>MAXIMUM_DIRECTORY_ENTRIES{return Err(error(ErrorKind::TooManyEntries,path,"Tree exceeds 4096 total entries"));}for name in names{let child=if suffix.is_empty(){name}else{format!("{suffix}/{name}")};validate_relative(&child)?;pending.push(child);}}
            let after=native::stamp(&file).map_err(|e|io(&relative,e))?;let current=native::stamp(&native::open_in(&self.root,&self.anchor,&relative).map_err(|e|io(&relative,e))?).map_err(|e|io(&relative,e))?;if before!=after||before!=current{return Err(error(ErrorKind::Conflict,&relative,"Tree changed during observation"));}nodes.push(TreeNode{suffix,stamp:before,directory:facts.is_dir()});tick(progress,Stage::Checking,nodes.len()as u64,None);
        }checkpoint(cancel,path)?;nodes.sort_by(|a,b|a.suffix.cmp(&b.suffix));Ok(nodes.into())
    }

    fn projected_tree(&self,destination:&str,nodes:&[TreeNode])->Result<(),Error>{
        validate_tree_projection(self.root.to_string_lossy().encode_utf16().count(),destination,nodes)
    }
}


impl Workspace{
    fn destination(&self,path:&str)->Result<(),Error>{validate_relative(path)?;bounded(&self.root.join(path))?;if let Some((parent,_))=path.rsplit_once('/'){let facts=native::open_in(&self.root,&self.anchor,parent).and_then(|f|f.metadata()).map_err(|e|error(ErrorKind::Boundary,path,e))?;if !facts.is_dir(){return Err(error(ErrorKind::Boundary,path,"Physical destination directory required"));}self.physical(parent,false)?;}Ok(())}

    /// 🔎️ Observes a physical entry without granting authority over another spelling.
    pub fn inspect_entry(&self,path:&str,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<EntryRevision,Error>{
        checkpoint(cancel,path)?;self.physical(path,false)?;let file=native::open_in(&self.root,&self.anchor,path).map_err(|e|io(path,e))?;let facts=file.metadata().map_err(|e|io(path,e))?;
        if !facts.is_file()&&!facts.is_dir(){return Err(error(ErrorKind::NotFile,path,"Regular file or directory required"));}
        let stamp=native::stamp(&file).map_err(|e|io(path,e))?;tick(progress,Stage::Checking,1,Some(1));checkpoint(cancel,path)?;
        let current=native::stamp(&native::open_in(&self.root,&self.anchor,path).map_err(|e|io(path,e))?).map_err(|e|io(path,e))?;
        if stamp!=current{return Err(error(ErrorKind::Conflict,path,"Entry changed during inspection"));}let nodes=if facts.is_dir(){self.tree_census(path,cancel,progress)?}else{Arc::from([TreeNode{suffix:String::new(),stamp:stamp.clone(),directory:false}])};if nodes.first().is_none_or(|node|node.stamp!=stamp){return Err(error(ErrorKind::Conflict,path,"Entry changed during tree observation"));}Ok(EntryRevision{root:self.root.clone(),path:path.into(),stamp,directory:facts.is_dir(),nodes})
    }

    pub(crate) fn entry_event(&self,journal:&Journal,id:&str,phase:&str,action:&str,source:&str,destination:&str,directory:bool,stamp:Option<&Stamp>,fingerprint:Option<&str>,status:&str)->Result<(),Error>{
        let store=&journal.path;let anchor=&journal.anchor;let(root,namespace)=self.history_namespace(journal)?;let name=format!("{id}.{phase}");bounded(&store.join(&name))?;let mut file=native::create_in(store,anchor,&name,true).map_err(|e|io(source,e))?;let identity=stamp.map_or((0,0),|s|s.identity);
        file.write_all(format!("source-entry-{phase}-v1\n{action}\n{source}\n{destination}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{status}\n",if directory{"directory"}else{"file"},identity.0,identity.1,root.identity.0,root.identity.1,namespace.identity.0,namespace.identity.1,fingerprint.unwrap_or("-")).as_bytes()).map_err(|e|io(source,e))?;file.sync_all().map_err(|e|io(source,e))?;
        native::sync_parents(store,anchor,&name,store,anchor,&name).map_err(|e|io(source,e))
    }

    fn retained_proof(&self,name:&str,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<RetainedProof,Error>{self.history_recovery_proof(name,cancel,progress)}

    /// 📃️ Creates one bounded document using an authenticated staged identity and exclusive publication.
    pub fn create_file(&self,path:&str,text:&str,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<Document,Error>{
        checkpoint(cancel,path)?;self.destination(path)?;validate_text(text)?;let journal=self.store(cancel,progress)?;let store=&journal.path;let anchor=&journal.anchor;let id=command_id();let stage=format!("{id}.created");bounded(&store.join(&stage))?;let mut file=native::create_in(&store,&anchor,&stage,true).map_err(|e|io(path,e))?;for chunk in text.as_bytes().chunks(16384){checkpoint(cancel,path)?;file.write_all(chunk).map_err(|e|io(path,e))?;tick(progress,Stage::Staging,file.metadata().map_err(|e|io(path,e))?.len(),Some(text.len()as u64));}file.sync_all().map_err(|e|io(path,e))?;let expected=native::stamp(&file).map_err(|e|io(path,e))?;drop(file);self.entry_event(&journal,&id,"intent","create-file",path,path,false,Some(&expected),Some(&bytes_fingerprint(text.as_bytes())),"prepared")?;
        tick(progress,Stage::Publishing,0,Some(1));checkpoint(cancel,path)?;self.destination(path)?;native::move_no_replace(&store,&anchor,&stage,&self.root,&self.anchor,path).map_err(|e|movement_error(path,e))?;let result=(||{native::sync_parents(&store,&anchor,&stage,&self.root,&self.anchor,path).map_err(|e|io(path,e))?;let settled=AtomicBool::new(false);let document=self.load(path,&settled,progress)?;let matches=matching(&expected,&document.revision.stamp)&&document.text==text;self.entry_event(&journal,&id,"outcome","create-file",path,path,false,Some(&document.revision.stamp),Some(&bytes_fingerprint(document.text.as_bytes())),if matches{"committed"}else{"conflict"})?;if !matches{return Err(error(ErrorKind::Conflict,path,"Created destination changed during publication"));}tick(progress,Stage::Complete,1,Some(1));Ok(document)})();result.map_err(|mut failure|{failure.recovery_path=Some(self.root.join(path).to_string_lossy().into_owned());failure})
    }

    /// 📁️ Creates an empty folder by publishing its preobserved staged inode exclusively.
    pub fn create_directory(&self,path:&str,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<Entry,Error>{
        checkpoint(cancel,path)?;self.destination(path)?;let journal=self.store(cancel,progress)?;let store=&journal.path;let anchor=&journal.anchor;let id=command_id();let stage=format!("{id}.created");bounded(&store.join(&stage))?;native::create_directory_in(&store,&anchor,&stage).map_err(|e|io(path,e))?;let relative=store.strip_prefix(&self.root).map_err(|_|error(ErrorKind::Boundary,path,"Rooted event segment required"))?.to_string_lossy().replace('\\',"/");let nodes=self.tree_census(&format!("{relative}/{stage}"),cancel,progress)?;let expected=&nodes[0].stamp;let before=tree_fingerprint(&nodes);self.entry_event(&journal,&id,"intent","create-directory",path,path,true,Some(expected),Some(&before),"prepared")?;
        tick(progress,Stage::Publishing,0,Some(1));checkpoint(cancel,path)?;self.destination(path)?;native::move_no_replace(&store,&anchor,&stage,&self.root,&self.anchor,path).map_err(|e|movement_error(path,e))?;let result=(||{native::sync_parents(&store,&anchor,&stage,&self.root,&self.anchor,path).map_err(|e|io(path,e))?;let settled=AtomicBool::new(false);let observed=self.inspect_entry(path,&settled,progress)?;let fingerprint=tree_fingerprint(&observed.nodes);let matches=observed.directory&&tree_matches(&nodes,&observed.nodes)&&fingerprint==before;self.entry_event(&journal,&id,"outcome","create-directory",path,path,true,Some(&observed.stamp),Some(&fingerprint),if matches{"committed"}else{"conflict"})?;if !matches{return Err(error(ErrorKind::Conflict,path,"Created folder changed during publication"));}tick(progress,Stage::Complete,1,Some(1));Ok(entry(path,true))})();result.map_err(|mut failure|{failure.recovery_path=Some(self.root.join(path).to_string_lossy().into_owned());failure})
    }

    fn move_entry(&self,path:&str,expected:&EntryRevision,destination:Option<&str>,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<(String,String,bool),Error>{
        checkpoint(cancel,path)?;if expected.root!=self.root||expected.path!=path{return Err(error(ErrorKind::Conflict,path,"Revision belongs to another entry"));}if let Some(to)=destination{self.destination(to)?;if to==path||to.starts_with(&format!("{path}/")){return Err(error(ErrorKind::InvalidPath,to,"Distinct destination outside the source required"));}}
        let journal=self.store(cancel,progress)?;let store=&journal.path;let anchor=&journal.anchor;let observed=self.inspect_entry(path,cancel,progress)?;if observed!=*expected{return Err(error(ErrorKind::Conflict,path,"Entry changed since inspection"));}
        let before=if expected.directory{tree_fingerprint(&expected.nodes)}else{let(fingerprint,stamp)=self.content_fingerprint(path,cancel,progress)?;if stamp!=expected.stamp{return Err(error(ErrorKind::Conflict,path,"File changed before content verification"));}fingerprint};
        let id=command_id();let retained=format!("{id}.retained");let to=destination.map(str::to_owned).unwrap_or_else(||format!("{}/{retained}",store.strip_prefix(&self.root).unwrap().to_string_lossy().replace('\\',"/")));self.projected_tree(&to,&expected.nodes)?;let action=if destination.is_some(){"rename"}else{"retain"};self.entry_event(&journal,&id,"intent",action,path,&to,expected.directory,Some(&expected.stamp),Some(&before),"prepared")?;
        if self.inspect_entry(path,cancel,progress)?!=*expected{return Err(error(ErrorKind::Conflict,path,"Entry changed before publication"));}tick(progress,Stage::Publishing,0,Some(1));checkpoint(cancel,path)?;
        if destination.is_some(){native::move_no_replace(&self.root,&self.anchor,path,&self.root,&self.anchor,&to)}else{native::move_no_replace(&self.root,&self.anchor,path,&store,&anchor,&retained)}.map_err(|e|movement_error(path,e))?;
        let recovery_path=self.root.join(&to).to_string_lossy().into_owned();let result=(||{let settled=AtomicBool::new(false);let file=native::open_in(&self.root,&self.anchor,&to).map_err(|e|io(path,e))?;let stamp=native::stamp(&file).map_err(|e|io(path,e))?;let facts=file.metadata().map_err(|e|io(path,e))?;
            let mut fingerprint=None;let matches=if facts.is_dir(){match self.tree_census(&to,&settled,progress){Ok(nodes)=>{fingerprint=Some(tree_fingerprint(&nodes));expected.directory&&tree_matches(&expected.nodes,&nodes)},Err(_)=>false}}else if facts.is_file(){match self.content_fingerprint(&to,&settled,progress){Ok((hash,current))=>{let matches=!expected.directory&&matching(&expected.stamp,&current)&&hash==before;fingerprint=Some(hash);matches},Err(_)=>false}}else{false};
            self.entry_event(&journal,&id,"outcome",action,path,&to,facts.is_dir(),Some(&stamp),fingerprint.as_deref(),if matches{"committed"}else{"conflict"})?;native::sync_parents(&self.root,&self.anchor,path,&self.root,&self.anchor,&to).map_err(|e|io(path,e))?;if !matches{return Err(error(ErrorKind::Conflict,path,"Move committed with a changed observed entry; inspect the actual recovery destination"));}tick(progress,Stage::Complete,1,Some(1));Ok((id,to,expected.directory))})();result.map_err(|mut failure|{failure.recovery_path=Some(recovery_path);failure})
    }

    /// 🏷️ Moves an observed file or complete bounded folder to an exclusively absent destination.
    pub fn rename_entry(&self,path:&str,expected:&EntryRevision,destination:&str,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<Entry,Error>{let(_,to,directory)=self.move_entry(path,expected,Some(destination),cancel,progress)?;Ok(entry(&to,directory))}

    /// 🧺️ Retains the actual removed entry in authenticated local event history.
    pub fn retain_entry(&self,path:&str,expected:&EntryRevision,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<RetainedEntry,Error>{let(id,to,directory)=self.move_entry(path,expected,None,cancel,progress)?;Ok(RetainedEntry{command_id:id,path:path.into(),recovery_path:self.root.join(to).to_string_lossy().into_owned(),directory})}
}

impl Workspace{
    fn recovery_entry(&self,path:&Path)->Result<(String,String,String),Error>{
        let relative=if path.is_absolute(){path.strip_prefix(&self.root).map_err(|_|error(ErrorKind::Boundary,&path.to_string_lossy(),"Recovery belongs to another workspace"))?}else{path};let pieces=relative.components().collect::<Vec<_>>();if pieces.len()<4||pieces[0].as_os_str()!=STATE||pieces[1].as_os_str()!="segments"||pieces.iter().any(|piece|!matches!(piece,std::path::Component::Normal(_))){return Err(error(ErrorKind::Boundary,&path.to_string_lossy(),"Selected retained entry required"));}let names=pieces.iter().map(|piece|piece.as_os_str().to_str().ok_or_else(||error(ErrorKind::InvalidPath,"","Unicode recovery path required"))).collect::<Result<Vec<_>,_>>()?;let segment=names[2];if segment.len()!=8||!segment.bytes().all(|b|b.is_ascii_digit()||matches!(b,b'a'..=b'f')){return Err(error(ErrorKind::Boundary,segment,"Canonical retained segment required"));}let artifact=names[3];if ![".retained",".new",".before"].iter().any(|suffix|artifact.ends_with(suffix)){return Err(error(ErrorKind::Boundary,artifact,"Retained command namespace required"));}let name=names[1..4].join("/");let suffix=names[4..].join("/");if !suffix.is_empty(){validate_relative(&suffix)?;}let full=names.join("/");bounded(&self.root.join(&full))?;Ok((name,suffix,full))
    }

    fn recovery_tree(&self,name:&str,proof:&RetainedProof,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<Arc<[TreeNode]>,Error>{
        let nodes=self.tree_census(&format!("{STATE}/{name}"),cancel,progress)?;if nodes.first().is_none_or(|root|root.stamp.identity!=proof.identity)||proof.fingerprint.as_deref()!=Some(tree_fingerprint(&nodes).as_str())||self.retained_proof(name,cancel,progress)?!=*proof{return Err(error(ErrorKind::Conflict,name,"Authenticated retained tree changed"));}Ok(nodes)
    }

    pub(super) fn load_retained(&self,path:&Path,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<Document,Error>{
        let(name,suffix,relative)=self.recovery_entry(path)?;let proof=self.retained_proof(&name,cancel,progress)?;if proof.directory&&suffix.is_empty(){return Err(error(ErrorKind::NotFile,&relative,"Select a retained file inside this folder"));}
        let observed=if proof.directory{let nodes=self.recovery_tree(&name,&proof,cancel,progress)?;Some(nodes.iter().find(|node|node.suffix==suffix).ok_or_else(||error(ErrorKind::Boundary,&relative,"Retained descendant was not observed"))?.stamp.clone())}else{if !suffix.is_empty(){return Err(error(ErrorKind::Boundary,&relative,"A retained file has no descendants"));}None};
        let physical=self.root.join(&relative);let(bytes,stamp)=self.read_physical(&physical,&relative,cancel,progress)?;if observed.as_ref().is_some_and(|value|*value!=stamp)||!proof.directory&&(stamp.identity!=proof.identity||proof.fingerprint.as_deref()!=Some(bytes_fingerprint(&bytes).as_str()))||self.retained_proof(&name,cancel,progress)?!=proof{return Err(error(ErrorKind::Conflict,&relative,"Authenticated retained file changed"));}
        let text=String::from_utf8(bytes.to_vec()).map_err(|_|error(ErrorKind::NotText,&relative,"Strict UTF-8 retained source required"))?;validate_text(&text)?;let path=physical.to_string_lossy().into_owned();tick(progress,Stage::Complete,bytes.len()as u64,Some(bytes.len()as u64));Ok(Document{path:path.clone(),text,revision:Revision{root:self.root.clone(),path,stamp,bytes}})
    }

    /// 🕰️ Lists authenticated retained roots or one bounded retained folder without save authority.
    pub fn list_recovery(&self,path:&str,cancel:&AtomicBool,progress:&mut dyn FnMut(Progress))->Result<Vec<Entry>,Error>{
        checkpoint(cancel,path)?;let mut rows=Vec::new();if path.is_empty(){return Ok(self.history_page(None,cancel,progress)?.entries);}
        else{let(name,suffix,relative)=self.recovery_entry(Path::new(path))?;let proof=self.retained_proof(&name,cancel,progress)?;if !proof.directory{return Err(error(ErrorKind::NotFile,path,"Retained directory required"));}let nodes=self.recovery_tree(&name,&proof,cancel,progress)?;if !nodes.iter().any(|node|node.suffix==suffix&&node.directory){return Err(error(ErrorKind::NotFile,path,"Retained directory descendant required"));}let prefix=if suffix.is_empty(){String::new()}else{format!("{suffix}/")};for node in nodes.iter(){checkpoint(cancel,path)?;let Some(rest)=node.suffix.strip_prefix(&prefix)else{continue};if rest.is_empty()||rest.contains('/'){continue;}let physical=self.root.join(&relative).join(rest);bounded(&physical)?;rows.push(Entry{path:physical.to_string_lossy().into_owned(),name:rest.into(),directory:node.directory});tick(progress,Stage::Listing,rows.len()as u64,None);}}
        rows.sort_by(|a,b|b.directory.cmp(&a.directory).then(a.name.as_bytes().cmp(b.name.as_bytes())));checkpoint(cancel,path)?;tick(progress,Stage::Complete,rows.len()as u64,Some(rows.len()as u64));Ok(rows)
    }
}
